-- Generated by Supabase CLI migration new. NEW application only.
-- No legacy 未定 rows are converted by this additive schema migration.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='60s';
DO $$ BEGIN
 IF (SELECT count(*) FROM public.ageful_migration_target)<>1 OR NOT EXISTS
 (SELECT 1 FROM public.ageful_migration_target WHERE project_ref='ufawaiddntqqbjhycbxn') THEN
 RAISE EXCEPTION 'Wrong project: pending new prospects belong to the new application only'; END IF;
END $$;
ALTER TABLE public.projects ADD COLUMN customer_pending boolean NOT NULL DEFAULT false;
ALTER TABLE public.projects DROP CONSTRAINT owner_unconfirmed_consistent;
ALTER TABLE public.projects ADD CONSTRAINT owner_unconfirmed_consistent CHECK(
 (customer_pending AND customer_id IS NULL AND previous_owner_customer_id IS NULL AND owner_unconfirmed_on IS NULL) OR
 (NOT customer_pending AND ((owner_unconfirmed_on IS NULL AND customer_id IS NOT NULL) OR
 (owner_unconfirmed_on IS NOT NULL AND customer_id IS NULL AND previous_owner_customer_id IS NOT NULL))));
ALTER TABLE public.prospects ADD COLUMN new_project_id bigint REFERENCES public.projects(id) ON DELETE RESTRICT;
ALTER TABLE public.prospects ADD CONSTRAINT prospect_new_project_exclusive CHECK(new_project_id IS NULL OR
 (ownership_project_id IS NULL AND ownership_state IS NULL AND candidate_customer_id IS NULL));
CREATE UNIQUE INDEX prospects_new_project_idx ON public.prospects(new_project_id) WHERE new_project_id IS NOT NULL;
CREATE TABLE public.new_prospect_events(
 operation_key uuid PRIMARY KEY,request_hash text NOT NULL,actor_user_id uuid NOT NULL,
 action text NOT NULL CHECK(action IN('create','assign','legacy_classify')),
 project_id bigint NOT NULL REFERENCES public.projects(id) ON DELETE RESTRICT,
 prospect_id bigint NOT NULL REFERENCES public.prospects(id) ON DELETE RESTRICT,
 before_snapshot jsonb NOT NULL,after_snapshot jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.new_prospect_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.new_prospect_events FROM PUBLIC,anon,authenticated;

CREATE FUNCTION public.guard_new_prospect_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN
 IF current_setting('ageful.new_prospect_write',true)='yes' THEN RETURN coalesce(NEW,OLD); END IF;
 IF TG_OP='DELETE' THEN
  IF OLD.new_project_id IS NOT NULL THEN RAISE EXCEPTION '発電所に紐づく見込みは削除できません'; END IF;
  RETURN OLD;
 END IF;
 IF TG_OP='INSERT' AND NEW.new_project_id IS NOT NULL THEN RAISE EXCEPTION '顧客未定の案件は専用操作で登録してください'; END IF;
 IF TG_OP='UPDATE' AND (OLD.new_project_id IS NOT NULL OR NEW.new_project_id IS NOT NULL) AND
 (NEW.new_project_id IS DISTINCT FROM OLD.new_project_id OR NEW.converted_customer_id IS DISTINCT FROM OLD.converted_customer_id
 OR NEW.converted_at IS DISTINCT FROM OLD.converted_at OR NEW.customer_name IS DISTINCT FROM OLD.customer_name
 OR NEW.customer_name_kana IS DISTINCT FROM OLD.customer_name_kana OR NEW.project_name IS DISTINCT FROM OLD.project_name
 OR NEW.ownership_project_id IS DISTINCT FROM OLD.ownership_project_id) THEN RAISE EXCEPTION '顧客は「顧客を設定」から変更してください'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_new_prospect_identity BEFORE INSERT OR UPDATE OR DELETE ON public.prospects FOR EACH ROW EXECUTE FUNCTION public.guard_new_prospect_identity();
CREATE FUNCTION public.guard_pending_project() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN
 IF current_setting('ageful.new_prospect_write',true)='yes' THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' AND NEW.customer_id IS DISTINCT FROM OLD.customer_id
 AND EXISTS(SELECT 1 FROM public.prospects WHERE new_project_id=OLD.id)
 AND current_setting('ageful.billing_runtime_write',true) IS DISTINCT FROM 'yes' THEN
 RAISE EXCEPTION '顧客の変更は専用操作で行ってください'; END IF;
 IF (TG_OP='INSERT' AND NEW.customer_pending) OR
 (TG_OP='UPDATE' AND (NEW.customer_pending IS DISTINCT FROM OLD.customer_pending OR
 (OLD.customer_pending AND NEW.customer_id IS DISTINCT FROM OLD.customer_id))) THEN
 RAISE EXCEPTION '顧客未定の設定は専用操作で行ってください'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER guard_pending_project BEFORE INSERT OR UPDATE ON public.projects FOR EACH ROW EXECUTE FUNCTION public.guard_pending_project();

CREATE FUNCTION public.new_prospect_write(p_key uuid,p_request jsonb) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a text:=p_request->>'action';v jsonb:=p_request->'value';fingerprint text;
 old_event public.new_prospect_events%ROWTYPE;proj public.projects%ROWTYPE;pr public.prospects%ROWTYPE;cust public.customers%ROWTYPE;
 before_value jsonb:='{}';allowed text[]:=ARRAY['customer_name','customer_name_kana','project_name','loan_company','equipment','land_cost','loan_amount',
 'site_address','panel_kw','sales_company','referrer','lead_date','existing_customer_id','is_corporate','company_name','customer_undecided',
 'apply_tasks','contract_tasks','apply_sub_tasks','contract_sub_tasks'];
BEGIN
 PERFORM public.assert_billing_runtime_access();
 IF p_key IS NULL OR jsonb_typeof(p_request) IS DISTINCT FROM 'object' OR
 (SELECT count(*) FROM jsonb_object_keys(p_request))<>2 OR NOT(p_request ?& ARRAY['action','value']) OR
 jsonb_typeof(v) IS DISTINCT FROM 'object' OR a NOT IN('create','assign') THEN RAISE EXCEPTION '案件の登録内容を確認してください'; END IF;
 fingerprint:=encode(sha256(convert_to(jsonb_build_object('request',p_request,'actor',auth.uid())::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended(p_key::text,0));
 SELECT * INTO old_event FROM public.new_prospect_events WHERE operation_key=p_key;
 IF FOUND THEN
  IF old_event.request_hash IS DISTINCT FROM fingerprint OR old_event.actor_user_id IS DISTINCT FROM auth.uid() THEN
  RAISE EXCEPTION '同じ操作IDで別の内容は保存できません'; END IF;
  RETURN jsonb_build_object('completed',true,'prospectId',old_event.prospect_id,'projectId',old_event.project_id);
 END IF;
 PERFORM set_config('ageful.new_prospect_write','yes',true);
 PERFORM set_config('ageful.billing_runtime_write','yes',true);
 IF a='create' THEN
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE NOT(k=ANY(allowed))) OR
  jsonb_typeof(v->'project_name') IS DISTINCT FROM 'string' OR trim(v->>'project_name')='' OR
  nullif(v->>'existing_customer_id','') IS NOT NULL OR v->'customer_undecided' IS DISTINCT FROM 'true'::jsonb
  OR trim(coalesce(v->>'customer_name',''))<>'' OR trim(coalesce(v->>'customer_name_kana',''))<>''
  OR trim(coalesce(v->>'company_name',''))<>'' THEN RAISE EXCEPTION '発電所名・顧客未定の入力項目を確認してください'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(ARRAY['apply_tasks','contract_tasks','apply_sub_tasks','contract_sub_tasks']) k
   WHERE v ? k AND jsonb_typeof(v->k) IS DISTINCT FROM 'object') THEN RAISE EXCEPTION '確認項目の形式を確認してください'; END IF;
  INSERT INTO public.projects(customer_id,customer_pending,project_name,plant_name,site_address,panel_kw,sales_company,referrer,sales_price,land_cost)
  VALUES(NULL,true,trim(v->>'project_name'),trim(v->>'project_name'),nullif(v->>'site_address',''),nullif(v->>'panel_kw','')::numeric,
   nullif(v->>'sales_company',''),nullif(v->>'referrer',''),nullif(v->>'equipment','')::integer,nullif(v->>'land_cost','')::integer) RETURNING * INTO proj;
  INSERT INTO public.contracts(project_id) VALUES(proj.id);
  INSERT INTO public.prospects(customer_name,customer_name_kana,project_name,new_project_id,loan_company,equipment,land_cost,loan_amount,
   site_address,panel_kw,sales_company,referrer,lead_date,apply_status,contract_status,apply_tasks,contract_tasks,apply_sub_tasks,contract_sub_tasks)
  VALUES('顧客未定',NULL,proj.project_name,proj.id,nullif(v->>'loan_company',''),nullif(v->>'equipment','')::integer,
   nullif(v->>'land_cost','')::integer,nullif(v->>'loan_amount','')::integer,nullif(v->>'site_address',''),nullif(v->>'panel_kw','')::numeric,
   nullif(v->>'sales_company',''),nullif(v->>'referrer',''),nullif(v->>'lead_date','')::date,'未','未',
   coalesce(v->'apply_tasks','{}'),coalesce(v->'contract_tasks','{}'),coalesce(v->'apply_sub_tasks','{}'),coalesce(v->'contract_sub_tasks','{}')) RETURNING * INTO pr;
 ELSE
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(v) k WHERE k NOT IN('project','prospect','customerId')) OR
  jsonb_typeof(v->'project') IS DISTINCT FROM 'object' OR jsonb_typeof(v->'prospect') IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION '顧客を設定する案件を確認してください'; END IF;
  SELECT * INTO STRICT proj FROM public.projects WHERE id=(v->'project'->>'id')::bigint FOR UPDATE;
  SELECT * INTO STRICT pr FROM public.prospects WHERE id=(v->'prospect'->>'id')::bigint FOR UPDATE;
  IF to_jsonb(proj) IS DISTINCT FROM v->'project' OR to_jsonb(pr) IS DISTINCT FROM v->'prospect' OR
   NOT proj.customer_pending OR proj.customer_id IS NOT NULL OR pr.new_project_id IS DISTINCT FROM proj.id OR pr.converted_customer_id IS NOT NULL THEN
   RAISE EXCEPTION '案件が更新されています。開き直してください'; END IF;
  SELECT * INTO cust FROM public.customers WHERE id=(v->>'customerId')::bigint FOR KEY SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION '顧客が見つかりません'; END IF;
  IF trim(coalesce(cust.name,'')) IN('未定','顧客未定','引継ぎ先未定') AND nullif(trim(cust.company_name),'') IS NULL THEN
   RAISE EXCEPTION '未定ではなく実際の顧客を選択してください'; END IF;
  before_value:=jsonb_build_object('project',to_jsonb(proj),'prospect',to_jsonb(pr));
  UPDATE public.projects SET customer_id=cust.id,customer_pending=false WHERE id=proj.id RETURNING * INTO proj;
  UPDATE public.prospects SET converted_customer_id=cust.id,converted_at=clock_timestamp(),
   customer_name=coalesce(nullif(cust.company_name,''),cust.name),customer_name_kana=coalesce(nullif(cust.company_name_kana,''),cust.name_kana)
   WHERE id=pr.id RETURNING * INTO pr;
 END IF;
 INSERT INTO public.new_prospect_events(operation_key,request_hash,actor_user_id,action,project_id,prospect_id,before_snapshot,after_snapshot)
 VALUES(p_key,fingerprint,auth.uid(),a,proj.id,pr.id,before_value,jsonb_build_object('project',to_jsonb(proj),'prospect',to_jsonb(pr)));
 PERFORM set_config('ageful.new_prospect_write','no',true);
 PERFORM set_config('ageful.billing_runtime_write','no',true);
 RETURN jsonb_build_object('completed',true,'prospectId',pr.id,'projectId',proj.id);
END $$;
REVOKE ALL ON FUNCTION public.new_prospect_write(uuid,jsonb) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.new_prospect_write(uuid,jsonb) TO authenticated;

-- A customer-only legacy link cannot select a project safely once a new-style
-- project link exists. Stop both directions of legacy sync for that customer.
CREATE OR REPLACE FUNCTION public.billing_runtime_has_transfer(p_customer bigint) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM public.assert_billing_runtime_access();
 RETURN EXISTS(SELECT 1 FROM public.ownership_transfers WHERE from_customer_id=p_customer OR to_customer_id=p_customer)
 OR EXISTS(SELECT 1 FROM public.prospects WHERE new_project_id IS NOT NULL AND converted_customer_id=p_customer);
END $$;
REVOKE ALL ON FUNCTION public.billing_runtime_has_transfer(bigint) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_runtime_has_transfer(bigint) TO authenticated;

ALTER FUNCTION public.billing_runtime_snapshot() RENAME TO billing_runtime_snapshot_before_new_prospect;
REVOKE ALL ON FUNCTION public.billing_runtime_snapshot_before_new_prospect() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_runtime_snapshot() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM public.assert_billing_runtime_access();
 RETURN public.billing_runtime_snapshot_before_new_prospect()||jsonb_build_object('new_prospect_ready',true);
END $$;
REVOKE ALL ON FUNCTION public.billing_runtime_snapshot() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_runtime_snapshot() TO authenticated;
ALTER FUNCTION public.billing_runtime_backup() RENAME TO billing_runtime_backup_before_new_prospect;
REVOKE ALL ON FUNCTION public.billing_runtime_backup_before_new_prospect() FROM PUBLIC,anon,authenticated;
CREATE FUNCTION public.billing_runtime_backup() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 PERFORM public.assert_billing_runtime_access();
 RETURN public.billing_runtime_backup_before_new_prospect()||jsonb_build_object('new_prospect_ready',true,'new_prospect_events',
 coalesce((SELECT jsonb_agg(to_jsonb(e) ORDER BY created_at,operation_key) FROM public.new_prospect_events e),'[]'::jsonb));
END $$;
REVOKE ALL ON FUNCTION public.billing_runtime_backup() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.billing_runtime_backup() TO authenticated;
NOTIFY pgrst,'reload schema';
COMMIT;
